// Imagery policy:
//  1. Openly-licensed photography from Openverse (CC0 / CC BY / CC BY-SA,
//     commercial use allowed), always shown with credit and license.
//  2. When no suitable photo theme fits, a thumbnail generated by The Daily SI
//     itself (/api/thumb), labelled as generated.
// Publisher photos from news feeds are never used: they are copyrighted.

import type { Story } from "./desk.ts";
import { hashId } from "./desk.ts";

export type Art = {
  src: string;
  alt: string;
  kind: "photo" | "generated";
  credit?: string;
  license?: string;
  licenseUrl?: string;
  sourceUrl?: string;
};

// Visual themes, matched against the story. Order matters: first match wins.
const THEMES: { re: RegExp; query: string; key: string }[] = [
  { re: /\b(humanoid|robots?|robotics|optimus|figure ai)\b/i, query: "humanoid robot", key: "robot" },
  { re: /\b(data ?cent(er|re)s?|stargate|supercomputer|gigawatt|power plant|nuclear)\b/i, query: "data center servers", key: "datacenter" },
  { re: /\b(chips?|GPUs?|semiconductor|nvidia|TSMC|wafer|export controls?)\b/i, query: "semiconductor chip", key: "chip" },
  { re: /\b(congress|senate|parliament|regulat\w*|AI act|white house|legislat\w*|lawmakers|EU)\b/i, query: "parliament building", key: "policy" },
  { re: /\b(jobs?|workers?|layoffs?|employment|workforce|labor|labour|hiring)\b/i, query: "office workers", key: "work" },
  { re: /\b(court|lawsuit|sues?|judge|copyright)\b/i, query: "courthouse", key: "court" },
  { re: /\b(hospital|medical|doctors?|drug discovery|biolog\w*|protein)\b/i, query: "laboratory research", key: "lab" },
];

type OpenverseResult = {
  id: string;
  title?: string;
  creator?: string;
  license: string;
  license_version?: string;
  license_url?: string;
  foreign_landing_url?: string;
  thumbnail?: string;
  url: string;
  width?: number;
  height?: number;
  mature?: boolean;
};

async function openverse(query: string): Promise<OpenverseResult[]> {
  const url =
    "https://api.openverse.org/v1/images/?" +
    new URLSearchParams({ q: query, license_type: "commercial", page_size: "20", aspect_ratio: "wide", mature: "false" });
  try {
    const res = await fetch(url, {
      headers: { "User-Agent": "TheDailySI/1.0 (news site; https://github.com/adonisgashi-alt/dailySI)" },
      // A handful of themes, cached for a day: a tiny, polite request volume.
      next: { revalidate: 86400 },
      signal: AbortSignal.timeout(6000),
    });
    if (!res.ok) return [];
    const json = (await res.json()) as { results?: OpenverseResult[] };
    return (json.results ?? []).filter((r) => !r.mature && r.thumbnail && (!r.width || r.width >= 600));
  } catch {
    return [];
  }
}

export function generatedArt(story: Pick<Story, "id" | "headline">): Art {
  return {
    src: `/api/thumb/${story.id}?t=${encodeURIComponent(story.headline.slice(0, 120))}`,
    alt: `Generated illustration for: ${story.headline}`,
    kind: "generated",
    credit: "Generated by The Daily SI",
  };
}

export async function artFor(stories: Story[]): Promise<Map<string, Art>> {
  const art = new Map<string, Art>();
  const byTheme = new Map<string, Story[]>();
  for (const s of stories) {
    const text = `${s.headline} ${s.summary}`;
    const theme = THEMES.find((t) => t.re.test(text));
    if (!theme) {
      art.set(s.id, generatedArt(s));
      continue;
    }
    byTheme.set(theme.key, [...(byTheme.get(theme.key) ?? []), s]);
  }

  await Promise.all(
    [...byTheme.entries()].map(async ([key, list]) => {
      const theme = THEMES.find((t) => t.key === key)!;
      const results = await openverse(theme.query);
      const used = new Set<number>();
      for (const s of list) {
        if (!results.length) {
          art.set(s.id, generatedArt(s));
          continue;
        }
        // Deterministic pick per story so images don't shuffle on refresh;
        // avoid repeating a photo within the same edition when possible.
        let i = parseInt(hashId(s.id).slice(0, 6), 36) % results.length;
        for (let k = 0; k < results.length && used.has(i); k++) i = (i + 1) % results.length;
        if (used.has(i)) {
          art.set(s.id, generatedArt(s));
          continue;
        }
        used.add(i);
        const r = results[i];
        const lic = `${r.license.toUpperCase() === "CC0" ? "CC0" : `CC ${r.license.toUpperCase()}`}${r.license_version && r.license !== "cc0" ? ` ${r.license_version}` : ""}`;
        art.set(s.id, {
          src: r.thumbnail!,
          alt: r.title ? `${r.title} (illustrative photo)` : `Illustrative photo: ${theme.query}`,
          kind: "photo",
          credit: r.creator ? `Photo: ${r.creator}` : "Photo via Openverse",
          license: r.license === "pdm" ? "Public domain" : lic,
          licenseUrl: r.license_url,
          sourceUrl: r.foreign_landing_url,
        });
      }
    }),
  );
  return art;
}
